mapper.select:
SELECT COUNT(*)
FROM (
    SELECT CHILD_ENTERPRISE_ID, LEVEL
    FROM ENTERPRISE_HIERARCHY
    WHERE (EXPIRY_DATE IS NULL OR EXPIRY_DATE > SYSDATE)
    AND LEVEL <= 10
    START WITH PARENT_ENTERPRISE_ID = #{childEnterpriseId}
    CONNECT BY PRIOR CHILD_ENTERPRISE_ID = PARENT_ENTERPRISE_ID
) t
WHERE t.CHILD_ENTERPRISE_ID = #{parentEnterpriseId}

